import{_ as n,l,o as t,c as i,v as e,p as d,x as o,d as s,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"从加性注意力到点积","description":"","frontmatter":{"title":"从加性注意力到点积","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/additive-to-dot-product.md","filePath":"llm/additive-to-dot-product.md","lastUpdated":1789023840000}'),m={name:"llm/additive-to-dot-product.md"};function E(_,a,c,A,u,B){const r=l("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="从加性注意力到点积" tabindex="-1">从加性注意力到点积 <a class="header-anchor" href="#从加性注意力到点积" aria-label="Permalink to &quot;从加性注意力到点积&quot;">​</a></h1><div class="epigraph"><p>若查询与键已经躺在同一内积空间里，匹配分数就是点积；加性网络多出来的 tanh 层并不是寻址接口本身。</p><footer>—— 据 Luong, Pham &amp; Manning, Effective Approaches to Attention-based Neural Machine Translation, EMNLP 2015；Vaswani et al., NeurIPS 2017 整理</footer></div><p><a href="/llm/attention-content-address">注意力作为内容寻址</a>给出查询、槽、软地址、读出。本课不重画四件套。缺口是：Bahdanau 的 \\(s\\) 是一个小 MLP，每对 \\((q,m_j)\\) 都要跑。若先把查询和键线性映到同一 \\(\\mathbb{R}^{d_k}\\)，匹配可以用<a href="/llm/norm-cosine-projection">范数、余弦与投影</a>里的点积 \\(q^\\top k_j\\)，一次矩阵乘出全部分数。本课只完成这一替换。<strong>不</strong>写 \\(\\mathrm{softmax}(QK^\\top/\\sqrt{d})\\) 的完整缩放点积注意力，不写多头、不写因果自注意力——那是主干 <a href="/llm/sdpa">SDPA</a> 的课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加性打分表达力强，但在 \\(n\\) 个槽上无法收成一次 GEMM：tanh 挡在中间。机器翻译里 Luong 等人比较了点积、加性与「先把 \\(q\\) 映一下再点积」，发现点积在投影之后足够好，且更快。缺口是承认：内容匹配可以就是内积。尺度问题已经在范数课暴露——未归一点积含长度——但如何除 \\(\\sqrt{d_k}\\)、如何用温度，留给 SDPA 课，避免在基础课把主干第一公式讲完。</p><p>点积要求 \\(q\\) 与 \\(k_j\\) 同维。编码器 \\(h_j\\) 与解码器 \\(h_t\\) 维数不同时，先做线性投影。这不是新的寻址定义，是让内积合法的形状对齐——回到第一课。</p><h3 id="点积注意力不是已经训好的-transformer" tabindex="-1">点积注意力不是已经训好的 Transformer <a class="header-anchor" href="#点积注意力不是已经训好的-transformer" aria-label="Permalink to &quot;点积注意力不是已经训好的 Transformer&quot;">​</a></h3><p>把 \\(q^\\top k\\) 写出来，并不等于多层自注意力块。还没有残差流上的自匹配、没有头的切分、没有缩放与掩码的标准实现。本课的对象仍是编码器—解码器：查询来自解码步，键值来自源。自注意力（查询也来自同一序列）会把位置问题立刻暴露出来，那是下一课的入口，不是本课提前实现。</p><p><span class="marginnote">Luong 的 global dot-product 与 Bahdanau 同属「每步读全体源」。local 注意力再加窗口，本课不取。Vaswani 把点积配上缩放与多头；本课只借「点积可当作匹配」这一句，公式停在 \\(q^\\top k\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>投影：\\(q=W_q h^{\\mathrm{dec}}\\)，\\(k_j=W_k h_j^{\\mathrm{enc}}\\)，可选 \\(v_j=W_v h_j^{\\mathrm{enc}}\\)。分数 \\(e_j=q^\\top k_j\\)。权重与读出仍是 softmax 与加权和。形状：一批查询 \\((B,d_k)\\) 对键 \\((B,n,d_k)\\) 经批矩阵乘得 \\((B,n)\\)。加性则无法单用一次 GEMM 表达 tanh。工程动机与几何动机同时成立：同一内积空间里，夹角小则分数大。</p>',11)),(t(),d(p,null,{default:o(()=>[h(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADD%5B%22%E5%8A%A0%E6%80%A7%EF%BC%9Atanh%20%E5%B0%8F%E7%BD%91%E6%89%93%E5%88%86%22%5D%20--%3E%20SLOW%5B%22%E9%9A%BE%E4%BB%A5%E4%B8%80%E6%AC%A1%20GEMM%22%5D%0A%20%20DOT%5B%22%E7%82%B9%E7%A7%AF%EF%BC%9A%E5%90%8C%E7%A9%BA%E9%97%B4%E5%86%85%E7%A7%AF%22%5D%20--%3E%20GEMM%5B%22%E4%B8%80%E6%AC%A1%E7%9F%A9%E9%98%B5%E4%B9%98%E5%87%BA%E5%88%86%E6%95%B0%22%5D%0A%20%20DOT%20--%3E%20NEXT%5B%22%E7%BC%A9%E6%94%BE%E4%B8%8E%E5%A4%9A%E5%A4%B4%E4%BA%A4%E7%BB%99%20SDPA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内积把「内容相近」收成标量，与词向量课的余弦检索是同一几何，只是现在查询是动态的解码状态，不是静态词型。长度仍会污染分数：\\(\\|q\\|\\) 或 \\(\\|k\\|\\) 随层变化时，softmax 饱和——这正是后课要除 \\(\\sqrt{d}\\) 或先归一化的原因。本课点名隐患，不把缩放写进默认公式，以免与 SDPA 课重复推导。</p><p>若先对 \\(q\\) 与 \\(k\\) 做 \\(\\ell_2\\) 归一再点积，分数落在 \\([-1,1]\\)，饱和减轻，但丢掉了长度里可能有用的置信度。是否归一化是归纳偏置，不是对错。本课两者都不定为默认，只要求读实现时看清 \\(e_j\\) 是 \\(q^\\top k\\) 还是 \\(\\hat q^\\top\\hat k\\)。</p><p>从加性换到点积，寻址接口不变：仍是内容寻址。变的是匹配函数的归纳偏置（双线性 vs 一层 tanh）和计算图（GEMM vs 逐对 MLP）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义多头、不定义 \\(1/\\sqrt{d}\\)、不定义自注意力掩码。下一课<a href="/llm/why-need-position">位置还没进模型</a>问：若键可以任意置换，点积读出为何分不清次序。后课默认：匹配可以用点积；完整的缩放点积注意力在主干 SDPA，不在本课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内容匹配可以是同空间点积；加性 MLP 不是接口的必要部分。</li><li>点积能收成 GEMM；维数不同时先投影。</li><li>未缩放的点积仍有尺度饱和隐患，处理留给 SDPA。</li><li>本课仍是编解码读取，不是多层自注意力块。</li><li>出处：Luong et al., EMNLP 2015；Vaswani et al., NeurIPS 2017（点积作为匹配，细节见后课）。</li></ul>',8))])}const P=n(m,[["render",E]]);export{q as __pageData,P as default};
